export const PHOTO_BACKGROUNDS={mint:{label:'초록 정원',color:'#b6d2bf',floor:'#e7dec5'},sunset:{label:'살구 노을',color:'#e9bdab',floor:'#efdbc2'},night:{label:'별빛 밤',color:'#6d83a5',floor:'#aebcc3'}};
export const PHOTO_POSES={stand:'살짝 손 흔들기',sit:'폭신하게 앉기'};
export const PHOTO_MAX_COMPANIONS=6;
export const PHOTO_COMPANIONS={none:'도름이 혼자',chinchilla:'친칠라와 함께',armadillo:'아르마딜로와 함께',capybara:'카피바라와 함께','science-fly':'초파리와 함께','athletic-turtle':'운동 거북이와 함께','moa-playmate':'모아와 함께','cafe-dog':'카페 강아지와 함께','craft-beaver':'공방 비버와 함께','post-penguin':'우편 펭귄과 함께','photo-fox':'사진사 여우와 함께','principal-bear':'곰 교장선생님과 함께','math-redpanda':'레서판다 수학 친구와 함께','nurse-otter':'수달 보건 선생님과 함께','music-bird':'작은 새 음악 선생님과 함께','art-chameleon':'카멜레온 미술 선생님과 함께','baseball-tiger':'야구 호랑이와 함께','koala-barista':'코알라 바리스타와 함께','computer-robot-dog':'로봇 강아지와 함께','athletic-rabbit':'운동 토끼와 함께','gardener-hedgehog':'정원사 고슴도치와 함께'};
export const PHOTO_CAST=Object.freeze({chinchilla:'친칠라',armadillo:'아르마딜로',capybara:'카피바라','science-fly':'초파리','athletic-turtle':'운동 거북이','moa-playmate':'모아','cafe-dog':'카페 강아지','craft-beaver':'공방 비버','post-penguin':'우편 펭귄','photo-fox':'사진사 여우','principal-bear':'곰 교장선생님','math-redpanda':'레서판다 수학 친구','nurse-otter':'수달 보건 선생님','music-bird':'작은 새 음악 선생님','art-chameleon':'카멜레온 미술 선생님','baseball-tiger':'야구 호랑이','koala-barista':'코알라 바리스타','computer-robot-dog':'로봇 강아지','athletic-rabbit':'운동 토끼','gardener-hedgehog':'정원사 고슴도치'});
export function photoCast(config){if(!config||!Object.hasOwn(PHOTO_COMPANIONS,config.companion))return null;if(Object.hasOwn(config,'companions')){const ids=config.companions;return config.companion==='none'&&Array.isArray(ids)&&ids.length<=PHOTO_MAX_COMPANIONS&&ids.every(id=>Object.hasOwn(PHOTO_CAST,id))&&new Set(ids).size===ids.length?[...ids]:null;}return config.companion==='none'?[]:[config.companion];}
export const photoCastLabel=config=>{const ids=photoCast(config);return !ids?.length?'도름이 혼자':'도름이 + '+ids.map(id=>PHOTO_CAST[id]).join(' · ');};
export const WALL_SLOTS={'home.wall-left':{label:'창문 왼쪽 벽',x:-2.25,y:2.05,z:-3.385},'home.wall-right':{label:'창문 오른쪽 벽',x:2.25,y:2.05,z:-3.385}};
export const MAX_PHOTOS=6;
export const validPhotoId=id=>typeof id==='string'&&/^photo_[a-zA-Z0-9_-]{6,80}$/.test(id);
export function cleanPhoto(p){if(!p||!photoCast(p)||!validPhotoId(p.id)||!Object.hasOwn(PHOTO_BACKGROUNDS,p.background)||!Object.hasOwn(PHOTO_POSES,p.pose)||!Object.hasOwn(PHOTO_COMPANIONS,p.companion)||typeof p.createdAt!=='string'||p.createdAt.length>30||!Number.isFinite(Date.parse(p.createdAt)))return null;return {id:p.id,background:p.background,pose:p.pose,companion:p.companion,...(Object.hasOwn(p,'companions')?{companions:[...p.companions]}:{}),createdAt:p.createdAt};}
